public class Pipeline2Test {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.function.UnaryOperator<String> upper = s -> s.toUpperCase();
        java.util.function.UnaryOperator<String> addA = s -> s + "a";
        java.util.function.UnaryOperator<String> bang = s -> s + "!";
        java.util.function.UnaryOperator<String> dropFirst = s -> s.substring(1);
        try {
            check("empty pipeline returns the input unchanged", "abc",
                    Pipeline2.applyAll("abc", java.util.Collections.emptyList()));
            check("single step", "ABC",
                    Pipeline2.applyAll("abc", java.util.List.of(upper)));
            check("upper then append", "Xa",
                    Pipeline2.applyAll("x", java.util.List.of(upper, addA)));
            check("append then upper (order matters)", "XA",
                    Pipeline2.applyAll("x", java.util.List.of(addA, upper)));
            check("three steps chain left to right", "ELLO!",
                    Pipeline2.applyAll("hello", java.util.List.of(dropFirst, upper, bang)));
            check("same step twice", "hi!!",
                    Pipeline2.applyAll("hi", java.util.List.of(bang, bang)));
            check("empty string input", "A",
                    Pipeline2.applyAll("", java.util.List.of(addA, upper)));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

