public class Pipeline2 {

    public static String applyAll(String input,
            java.util.List<java.util.function.UnaryOperator<String>> steps) {
        String result = input;
        for (java.util.function.UnaryOperator<String> step : steps) {
            result = step.apply(result);
        }
        return result;
    }
}
